 function viewKey(){if(screen==='engineering')return 'engineering:'+engView+':'+engId+':'+engSection;if(screen==='methodDetail')return 'method:'+methodId+':'+methodSection+':'+methodStep;if(screen==='node')return 'node:'+s.lastNode+':'+section;if(screen==='techDetail')return 'tech:'+techId+':'+techSection;if(screen==='session')return 'question:'+session.mode+':'+session.ids[0]+':'+session.index+':'+session.done;if(screen==='lab'||screen==='labResult')return screen+':'+lab;if(screen==='leaveConfirm')return screen+':'+pending.kind;return screen||'tab:'+tab+':'+(tab===1?graphMode:tab===2?mode:tab===3?myView:'');}
 function reducedMotion(){return typeof window.matchMedia==='function'&&window.matchMedia('(prefers-reduced-motion: reduce)').matches;}
 function animateProgress(){Array.from(document.querySelectorAll('[data-progress-key]')).forEach(bar=>{const key=bar.dataset.progressKey,span=bar.querySelector('span'),target=Number(span.dataset.progressTarget),previous=progressValues[key];progressValues[key]=target;if(previous!==undefined&&previous!==target&&!reducedMotion()){span.style.transition='none';span.style.width=previous+'%';void span.offsetWidth;span.style.transition='';if(typeof window.requestAnimationFrame==='function')window.requestAnimationFrame(function(){span.style.width=target+'%';});else span.style.width=target+'%';}});}
 function completionStars(){return '<div class="completion-stars" aria-hidden="true">'+[0,1,2].map(i=>'<span class="star star-'+i+'">'+icon('star')+'</span>').join('')+'</div>';}
